fn toBase(n: Int, base: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let out: Text = "";
    let m: Int = n;
    loop m > 0 {
        let d: Int = m % base;
        out = digitChar(d) + out;
        m = m div base;
    }
    ret out;
}

