fn toBase(n: Int, base: Int) -> Text {
    let digits: Text = "0123456789ABCDEF";
    if n == 0 {
        ret "0";
    }
    let out: Text = "";
    let m: Int = n;
    loop m > 0 {
        let q = m / base;
        let rem: Int = m - q * base;
        out = digits[rem] + out;
        m = q;
    }
    ret out;
}

