    let rows: Int = length(grid);
    let count: Int = 0;
    loop dr in -1..2 {
        loop dc in -1..2 {
            let rr: Int = r + dr;
            let cc: Int = c + dc;
            let isSelf: Bool = dr == 0 && dc == 0;
            if !isSelf && rr >= 0 && rr < rows && cc >= 0 && cc < length(grid[rr]) {
