type Point {
    r: Int = 0;
    c: Int = 0;
}

@pure
fn samePoint(a: Point, b: Point) -> Bool {
    ret a.r == b.r && a.c == b.c;
}

fn bfs(maze: Text[], goal: Point) -> Int {
    let rows: Int = length(maze);
    let cols: Int = string_len(maze[0]);
    let dist: Int[][] = [];
    loop r in 0..rows {
        let row: Int[] = [];
        loop c in 0..cols {
            row = row + [-1];
        }
        dist = dist + [row];
    }
    let dr: Int[] = [-1, 1, 0, 0];
    let dc: Int[] = [0, 0, -1, 1];
    let queue: Point[] = [new Point { r: 0, c: 0 }];
    dist[0][0] = 0;
    let head: Int = 0;
    loop head < length(queue) {
        let cur: Point = queue[head];
        head = head + 1;
        if samePoint(cur, goal) {
            ret dist[cur.r][cur.c];
        }
        loop k in 0..4 {
            let nr: Int = cur.r + dr[k];
            let nc: Int = cur.c + dc[k];
            if nr >= 0 && nr < rows && nc >= 0 && nc < cols {
                let line: Text = maze[nr];
                if line[nc] == "." && dist[nr][nc] == -1 {
                    dist[nr][nc] = dist[cur.r][cur.c] + 1;
                    queue = queue + [new Point { r: nr, c: nc }];
                }
            }
        }
    }
    ret -1;
}

fn main() -> Void {
    let maze: Text[] = ["..#..", ".##.#", ".....", "#.#.#", "...#."];
    let goals: Point[] = [new Point { r: 2, c: 4 }, new Point { r: 4, c: 0 }, new Point { r: 4, c: 4 }];
    fx {
        loop g in goals {
            println("steps to (", g.r, ",", g.c, ") = ", bfs(maze, g));
        }
    }
    ret;
}

