fn upper(s: Text) -> Text {
    let out: Text = "";
    loop i in 0..string_len(s) {
        let c: Int = ord(s[i]);
        if c >= 97 && c <= 122 {
            out = out + chr(c - 32);
        } else {
            out = out + s[i];
        }
    }
    ret out;
}

fn main() -> Void {
    let sentence: Text = "the quick brown fox";
    let words: Text[] = split(sentence, " ");
    fx {
        loop w in words {
            println(upper(w));
        }
        println(upper(sentence));
    }
    ret;
}

